import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";

// bin/count-hooks.sh is the one source for the hook count. The docs data
// generator kept its own rule after #5079 changed that one, so the site said 161
// while every stamped surface said 163.
const ROOT = path.join(process.cwd(), "../..");

function countedTotal(): number {
	const out = execFileSync("bash", [path.join(ROOT, "bin/count-hooks.sh")], {
		encoding: "utf8",
	});
	const match = out.match(/TOTAL=(\d+)/);
	if (!match) throw new Error(`no TOTAL in: ${out}`);
	return Number(match[1]);
}

describe("generated docs data agrees with bin/count-hooks.sh", () => {
	const total = countedTotal();

	it.each(["plugins-data.ts", "shared-data.ts"])("%s", (file) => {
		const text = readFileSync(
			path.join(process.cwd(), "lib/generated", file),
			"utf8",
		);
		const match = text.match(/"hooks": (\d+)/);
		expect(match).not.toBeNull();
		expect(Number(match?.[1])).toBe(total);
	});
});
